def check_accelerator(msgid: Any, msgstr: Any, line_warns: Any) -> object {
    msgid = msgid.lower();
    msgstr = msgstr.lower();
    p1 = msgid.find('&');
    if (p1 >= 0) {
        a1 = msgid[p1:(p1 + 2)];
        p2 = msgstr.find('&');
        if ((p2 < 0) and (len(a1) > 1)) {
